import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('The Stale Closure', () => {
  test('Starts at 0', async () => {
    const { container: root } = render(<App />);
    const el = root.querySelector('#count');
if (!el.textContent.includes('0')) throw new Error('Should start at 0');
  });

  test('Single increment adds 1', async () => {
    const { container: root } = render(<App />);
    root.querySelector('#increment').click();
await tick();
const el = root.querySelector('#count');
if (!el.textContent.includes('1')) throw new Error('Should be 1 after one increment');
  });

  test('"Add 3" button adds exactly 3', async () => {
    const { container: root } = render(<App />);
    root.querySelector('#add-three').click();
await tick();
const el = root.querySelector('#count');
if (!el.textContent.includes('4')) throw new Error('Should be 4 (1 + 3), got: ' + el.textContent);
  });
});
